import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Operations at Scale. Alex Marangone from DigitalOcean","description":"","frontmatter":{"title":"Ceph Operations at Scale. Alex Marangone from DigitalOcean","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-09T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","容器化","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Operations_at_Scale._Alex_Marangone_from_DigitalOcean.md","filePath":"posts/2025/Ceph_Operations_at_Scale._Alex_Marangone_from_DigitalOcean.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Ceph_Operations_at_Scale._Alex_Marangone_from_DigitalOcean.md"};function n(r,a,p,s,_,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<p>Ceph 运维规模化实践分享会议中，Alex Marangone，DigitalOcean 存储系统团队成员，详细介绍了公司在 Ceph 运维方面的经验和实践。以下是对会议内容的总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>Alex 分享了 DigitalOcean 如何通过自动化、创新解决方案和高效的运维策略来管理其庞大的 Ceph 集群。DigitalOcean 拥有近 70 个 Ceph 集群，超过 250PB 的原始数据，30,000 多个 OSD，分布在全球 1,700 多个节点上，由一个仅五人的团队管理。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>自动化与效率</strong>：DigitalOcean 强调自动化在提高运维效率、减少人为错误和确保操作安全性和一致性方面的重要性。</p></li><li><p><strong>容器化应用</strong>：容器化帮助 DigitalOcean 解决了早期 Ceph 集群的稳定性问题，通过容器化实现了 OS 与 Ceph 版本的解耦，简化了升级过程。</p></li><li><p><strong>自定义部署工具</strong>：DigitalOcean 使用自定义的部署工具，而非上游的 Ceph 部署工具，以提高效率和适应性。</p></li><li><p><strong>操作安全性与自动化</strong>：DigitalOcean 使用 RADOS 锁机制来协调操作，确保同一时间只有一个操作可以修改集群状态。</p></li><li><p><strong>OSD 生命周期管理</strong>：DigitalOcean 开发了内部工具 Forman Storage Manager，用于管理 OSD 的整个生命周期，包括驱动器的更换、重新部署和健康检查。</p></li><li><p><strong>社区参与与贡献</strong>：DigitalOcean 加入 Ceph 基金会，并计划开源一些内部工具，如 Ceph 的 exporter 和 OSD 级别的监控工具。</p></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ol><li>继续推进自动化和容器化，以提高运维效率和稳定性。</li><li>开源内部工具，如 OSD 生命周期管理工具和监控 exporter。</li><li>积极参与 Ceph 社区项目，特别是在容器化、自动化和 Crimson 测试方面。</li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li>优化自动化流程，减少人为干预。</li><li>开源内部工具，并准备相关文档。</li><li>积极参与 Ceph 社区，贡献资源和知识。</li></ol><h3 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h3><p>本次会议详细介绍了 DigitalOcean 在 Ceph 运维方面的创新实践，为其他 Ceph 用户提供了宝贵的参考，尤其是在如何通过自动化和创新解决方案来应对大规模集群管理的挑战方面。此外，DigitalOcean 还表达了增加对 Ceph 社区贡献的意愿，并计划开源一些内部工具，推动 Ceph 生态的发展。</p>',11)])])}const d=e(o,[["render",n]]);export{g as __pageData,d as default};
